export interface WardrobeItem {
  id: string;
  name: string;
  url: string;
}

export interface OutfitLayer {
  garment: WardrobeItem | null; // null represents the base model layer
  poseImages: Record<string, string>; // Maps pose instruction to image URL
}

export type SubscriptionPlan = 'free' | 'pro';

export interface User {
  id: string;
  email: string;
  name: string;
  plan: SubscriptionPlan;
  subscriptionStatus: 'active' | 'inactive' | 'cancelled';
  generationsUsed: number;
  avatar?: string;
}

/**
 * @license
 * SPDX-License-Identifier: Apache-2.0
*/
import { User } from '../types';

const DB_KEY = 'saas_users_db';
const SESSION_KEY = 'saas_session_id';

const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// Mock Database methods
export const db = {
  getUsers: (): User[] => {
    const data = localStorage.getItem(DB_KEY);
    return data ? JSON.parse(data) : [];
  },

  saveUser: (user: User) => {
    const users = db.getUsers();
    const existingIndex = users.findIndex(u => u.id === user.id);
    if (existingIndex >= 0) {
      users[existingIndex] = user;
    } else {
      users.push(user);
    }
    localStorage.setItem(DB_KEY, JSON.stringify(users));

    // Update session if it's the current user
    const currentUser = db.getCurrentUser();
    if (currentUser && currentUser.id === user.id) {
        localStorage.setItem(SESSION_KEY, JSON.stringify(user));
    }
  },

  findUserByEmail: (email: string) => {
    return db.getUsers().find(u => u.email === email);
  },

  getCurrentUser: (): User | null => {
    const data = localStorage.getItem(SESSION_KEY);
    return data ? JSON.parse(data) : null;
  },

  login: async (email: string): Promise<User> => {
    await delay(800); // Simulate network
    const user = db.findUserByEmail(email);
    if (!user) throw new Error('User not found');
    localStorage.setItem(SESSION_KEY, JSON.stringify(user));
    return user;
  },

  signup: async (email: string, name: string): Promise<User> => {
    await delay(800);
    if (db.findUserByEmail(email)) throw new Error('Email already exists');

    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      email,
      name,
      plan: 'free',
      subscriptionStatus: 'inactive',
      generationsUsed: 0,
      avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${name}`
    };

    db.saveUser(newUser);
    localStorage.setItem(SESSION_KEY, JSON.stringify(newUser));
    return newUser;
  },

  logout: () => {
    localStorage.removeItem(SESSION_KEY);
  },

  upgradeSubscription: async (userId: string): Promise<User> => {
    await delay(1500); // Simulate PayPal processing
    const users = db.getUsers();
    const user = users.find(u => u.id === userId);
    if (!user) throw new Error('User not found');

    user.plan = 'pro';
    user.subscriptionStatus = 'active';
    db.saveUser(user);
    return user;
  }
};

