  const [isProcessingPayment, setIsProcessingPayment] = useState(false);

  useEffect(() => {
    // Check for existing session
    const checkSession = async () => {
        const currentUser = await db.getCurrentUser();
        if (currentUser) {
            setUser(currentUser);
            setCurrentView('dashboard');
        }
