const POSE_INSTRUCTIONS = [
  "Full frontal view, hands on hips",
  "Slightly turned, 3/4 view",
  "Side profile view",
  "Walking towards camera, confident stride",
  "Leaning against a wall, casual",
  "Sitting on a stool, elegant",
